/**
 * Changes the passphrase. Every stored secret and postal code is opened with
 * the current key and sealed again under a new key from the new passphrase,
 * in one transaction with the new key settings: either everything moves to
 * the new passphrase or nothing does, and the old one stops working at once.
 * If anything can't be opened (damaged, or sealed under an older key) nothing
 * changes, and the logins it belongs to are named so they can be put right
 * first. A partner only. The vault is left unlocked under the new key.
 */
changePassphrase(current: string, next: string, actor: Actor, audit: AuditFn): VaultStatus & { resealed: number } {
  if (actor.role !== 'partner') throw new UserFacingError('Only a partner can change the vault passphrase.')
  const row = this.keyRow()
  if (!row) throw new UserFacingError('The vault hasn’t been set up yet.')
  if (typeof next !== 'string' || next.normalize('NFKC').length < MIN_PASSPHRASE_LENGTH) {
    throw new UserFacingError(`Use a new passphrase of at least ${MIN_PASSPHRASE_LENGTH} characters.`)
  }
  if (typeof current === 'string' && current.normalize('NFKC') === next.normalize('NFKC')) {
    throw new UserFacingError('Choose a passphrase different from the current one.')
  }
  const oldKey = this.keyFor(current, row, audit, 'Vault passphrase change failed')
  const kdf = this.opts.kdf ?? DEFAULT_KDF
  const salt = randomBytes(16)
  const newKey = deriveKey(next, salt, kdf)
  const version = row.version + 1
  try {
    const secrets = this.db
      .prepare(
        `SELECT s.id, s.credential_id, s.field, s.label, s.secret_ct, s.secret_iv, s.secret_tag, s.key_version, v.platform
           FROM credential_secrets s JOIN credential_vault v ON v.id = s.credential_id ORDER BY s.id`
      )
      .all() as Array<Pick<SecretRow, 'id' | 'credential_id' | 'field' | 'label' | 'secret_ct' | 'secret_iv' | 'secret_tag' | 'key_version'> & { platform: string }>
    const codes = this.db
      .prepare('SELECT id, client_ref, code_ct, code_iv, code_tag, code_key_version FROM agent_authorisations WHERE code_ct IS NOT NULL ORDER BY id')
      .all() as Array<{ id: number; client_ref: string; code_ct: string; code_iv: string; code_tag: string; code_key_version: number | null }>

    // Open everything first: nothing is written unless all of it opens.
    const openedSecrets = secrets.map((s) => ({
      s,
      value: s.key_version === row.version ? this.open(oldKey, secretAad(s.credential_id, s.field, s.label), { ct: s.secret_ct, iv: s.secret_iv, tag: s.secret_tag }) : null
    }))
    const openedCodes = codes.map((c) => ({
      c,
      value: c.code_key_version === row.version ? this.open(oldKey, codeAad(c.id), { ct: c.code_ct, iv: c.code_iv, tag: c.code_tag }) : null
    }))
    const stuck = [
      ...openedSecrets.filter((o) => o.value === null).map((o) => `the ${SECRET_FIELDS[o.s.field]?.toLowerCase() ?? 'secret'} for ${o.s.platform}`),
      ...openedCodes.filter((o) => o.value === null).map((o) => `the authorisation code for client ${o.c.client_ref}`)
    ]
    if (stuck.length) {
      const named = stuck.slice(0, 5).join('; ')
      throw new UserFacingError(
        `Nothing was changed: ${stuck.length === 1 ? 'one stored item' : `${stuck.length} stored items`} can’t be opened with the current passphrase (${named}${stuck.length > 5 ? '; and more' : ''}). Remove or re-enter ${stuck.length === 1 ? 'it' : 'them'}, then change the passphrase.`
      )
    }

    this.db.transaction(() => {
      const putSecret = this.db.prepare('UPDATE credential_secrets SET secret_ct = ?, secret_iv = ?, secret_tag = ?, key_version = ? WHERE id = ?')
      const putCode = this.db.prepare('UPDATE agent_authorisations SET code_ct = ?, code_iv = ?, code_tag = ?, code_key_version = ? WHERE id = ?')
      this.db
        .prepare('INSERT INTO vault_keys (version, kdf, salt, n, r, p, verifier, created_by) VALUES (?, ?, ?, ?, ?, ?, ?, ?)')
        .run(version, 'scrypt', salt.toString('base64'), kdf.N, kdf.r, kdf.p, verifierFor(newKey).toString('base64'), actor.name)
      for (const { s, value } of openedSecrets) {
        const sealed = this.seal(newKey, secretAad(s.credential_id, s.field, s.label), value as string)
        putSecret.run(sealed.ct, sealed.iv, sealed.tag, version, s.id)
      }
      for (const { c, value } of openedCodes) {
        const sealed = this.seal(newKey, codeAad(c.id), value as string)
        putCode.run(sealed.ct, sealed.iv, sealed.tag, version, c.id)
      }
      // The old passphrase's settings go: nothing is sealed under them any more.
      this.db.prepare('DELETE FROM vault_keys WHERE version < ?').run(version)
      audit('Vault passphrase changed', 'vault_keys', version, { version: row.version }, { version, secrets_resealed: secrets.length, codes_resealed: codes.length })
    })()
  } catch (err) {
    newKey.fill(0)
    throw err
  } finally {
    oldKey.fill(0)
  }
  this.lock()
  this.key = newKey
  this.keyVersion = version
  this.lastUse = this.now()
  return { ...this.status(actor), resealed: 0 }
}

